#include <stdio.h>

int main(void) {
    int n = 0;
    if (scanf("%d", &n) != 1) {
        return 1;
    }

    int total = 0;
    for (int i = 0; i < n; i++) {
        int one = 0;
        if (scanf("%d", &one) != 1) {
            return 1;
        }
        total = total + one;
    }
    printf("一共 %d 条{unit}喵\n", total);
    return 0;
}
